import {project, externalUrl} from './project.mjs';
import {pwaState} from './pwa.mjs';
const escape = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function link(label, suffix = '') {
  const repo = externalUrl(project.repositoryUrl);
  return repo ? `<a class="button ghost" href="${escape(repo.replace(/\/$/,'') + suffix)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>` : `<button class="button ghost" data-action="github-preview">${label} ↗</button>`;
}
export function communityMarkup() {
  const pwa = pwaState();
  return `<section class="project-hero"><canvas class="project-starfield" aria-hidden="true"></canvas><figure class="ledger-model"><div class="ledger-model-stage"><img src="assets/symbol.svg" width="512" height="512" alt="Logo de NysaLedger"><canvas class="ledger-model-canvas" tabindex="0" role="img" aria-label="Logo 3D interactivo de NysaLedger" aria-describedby="ledger-model-hint"></canvas></div><figcaption id="ledger-model-hint">Arrastra para explorar · giro automático</figcaption><div class="ledger-model-controls"><button type="button" class="logo-action" data-logo-pause aria-pressed="false">Ⅱ Pausar</button><button type="button" class="logo-action" data-logo-reset>Restablecer ↺</button></div></figure><div><p class="eyebrow">UN PROYECTO DE <span class="project-nysasoft"><span class="project-brand-pink">&gt;_</span>NYSA<span class="project-brand-pink">SOFT</span></span></p><h1><span class="project-heading-word">Nysa</span><span class="project-ledger-word project-heading-word">Ledger</span></h1><p class="project-lead"><span class="project-heading-word">Tu</span> <span class="project-heading-word">control</span> <span class="project-heading-word">tributario,</span><br><span class="project-heading-word">en</span> <span class="project-heading-word">tu</span> <span class="project-heading-word">órbita.</span></p><p class="project-copy">Tus XML, ingresos, gastos y retenciones en un espacio claro. Gratis, sin registro y con tus datos en tu dispositivo.</p><div class="regional-scope"><span class="ecuador-flag" aria-hidden="true"></span><div><strong>Para Ecuador · En español</strong><p>Trabaja con comprobantes del SRI y resúmenes pensados para las obligaciones tributarias de Ecuador. Por eso, la aplicación está en español. No contempla sistemas tributarios de otros países.</p></div></div><div class="project-pills"><span>Gratis para usar</span><span>Sin registro</span><span>Sin anuncios</span></div><div class="project-actions"><button class="button primary" data-action="install">${pwa.installed?'Aplicación instalada ✓':'↓ Instalar NysaLedger'}</button><a class="button ghost" href="https://ko-fi.com/nysasoft" target="_blank" rel="noopener noreferrer"><span class="support-button-heart" aria-hidden="true">♡</span> Apoyar el proyecto ↗</a></div><p class="mini-note">${pwa.offlineReady?'✓ Aplicación preparada para abrir sin conexión en este navegador.':'La disponibilidad sin conexión se prepara después de la primera visita.'}</p></div></section>
  ${pwa.updateReady?'<div class="notice"><strong>Hay una nueva versión.</strong> Tus datos locales se conservan. Guarda los formularios que estés editando antes de actualizar. <button class="text-button" data-action="update-app">Revisar actualización ↗</button></div>':''}
  <section class="community-grid"><article class="panel"><div class="panel-body"><span class="project-symbol purple">⌘</span><h2>Crece con la comunidad.</h2><p>El código está en GitHub. Puedes estudiar cómo funciona, dar una estrella, reportar problemas y proponer mejoras.</p><div class="community-links">${link('Ver el código')}${link('Dar una estrella')}${link('Reportar un problema','/issues')}${link('Proponer un cambio','/pulls')}</div><p class="mini-note">${externalUrl(project.repositoryUrl)?'Puedes comentar propuestas y revisar cambios en GitHub.':'Repositorio público próximamente. Por ahora puedes explorar esta versión local.'}</p></div></article><article class="panel"><div class="panel-body"><span class="project-symbol pink">♡</span><h2>Gratis. Con tu apoyo.</h2><p>Si NysaLedger te ayuda, puedes apoyar su desarrollo. Los aportes son voluntarios: ninguna función depende de pagar.</p><a class="button ghost" href="https://ko-fi.com/nysasoft" target="_blank" rel="noopener noreferrer">Apoyar NysaLedger ↗</a><p class="mini-note">También puedes ayudar probando, compartiendo ideas, mejorando la documentación o revisando el código.</p></div></article></section>
  <section class="panel project-install"><div class="panel-body"><div><p class="eyebrow">TU ESCRITORIO. TU TELÉFONO.</p><h2>El mismo espacio, en formato app.</h2><p>Instálala desde un navegador compatible. En Android aparecerá en tu pantalla de inicio; en PC puede abrirse en su propia ventana.</p><p class="mini-note">Cada dispositivo guarda sus propios datos. Para llevarlos a otro, crea y restaura un respaldo cifrado. No hay sincronización automática.</p></div><button class="button primary" data-action="install">Ver cómo instalar ↗</button></div></section>
  <div class="notice info settings-note"><strong>Una ayuda para preparar, no para presentar.</strong> Esta versión importa y organiza XML; no emite facturas, no verifica su firma con el SRI y no presenta declaraciones. Revisa tu resumen antes de usarlo para declarar.</div>`;
}
export function supportMarkup() {
  const url = externalUrl(project.supportUrl);
  return `<div class="support-heart" aria-hidden="true">♡</div><h3>Que siga siendo útil. Y gratuito.</h3><p>Tu apoyo ayuda a dedicar tiempo a mejoras, pruebas y documentación. Usar NysaLedger no requiere pagar.</p>${url?`<a class="button primary" href="${escape(url)}" target="_blank" rel="noopener noreferrer">Apoyar en Ko-fi ↗</a><p class="form-hint">Continuarás en un servicio externo. Ningún XML ni dato de tu perfil se envía al abrir este enlace.</p>`:'<div class="notice info"><strong>Aportes monetarios todavía no habilitados.</strong> Estamos definiendo un medio compatible. Esta vista previa no solicita tarjetas ni realiza cobros.</div>'}<h3>También puedes apoyar sin dinero</h3><p>Prueba la demo, comparte tus ideas, deja una estrella en GitHub, abre un issue o envía un pull request. No adjuntes XML reales ni datos de clientes.</p><div class="form-buttons"><button class="button primary" data-action="close-modal">Entendido</button></div>`;
}
export function installationMarkup() {
  const state = pwaState();
  return `${state.installed?'<div class="notice info">NysaLedger ya está abierta como aplicación instalada.</div>':''}<h3>En Android</h3><p>Abre NysaLedger en Chrome y usa el menú <strong>⋮ → Instalar aplicación</strong> o <strong>Añadir a pantalla de inicio</strong>. Si el navegador ofrece la instalación directa, puedes usar el botón inferior.</p><h3>En PC</h3><p>En Chrome o Edge, usa el icono de instalación de la barra de direcciones o la opción de instalar del menú del navegador.</p><div class="notice info">La vista local <strong>127.0.0.1</strong> solo abre en esta computadora. Para instalar desde tu teléfono necesitaremos el enlace HTTPS cuando autorices la publicación. Todavía no hay una versión en Google Play.</div><p class="form-hint">La instalación no crea una cuenta ni sincroniza tus dispositivos. Conserva tus respaldos cifrados. ${state.offlineReady?'El contenido de la app ya está preparado para abrir sin conexión.':'La primera carga necesita conexión para preparar los archivos de la app.'}</p><div class="form-buttons"><button class="button ghost" data-action="close-modal">Cerrar</button>${state.canPrompt&&!state.installed?'<button class="button primary" data-action="install-now">Instalar ahora ↗</button>':''}</div>`;
}
